def get_stock_many(skus: list[str]) -> dict[str, int]:
    out = {}
    for sku in skus:
        resp = httpx.get(
            f"{settings.get('inventory', 'base_url')}/v2/stock/{sku}",
            timeout=settings.get("inventory", "timeout_s"),
        )
        resp.raise_for_status()
        out[sku] = resp.json()["available"]
    return out
